-- Docs backup generated from current database content
-- Generated by GET /config/docs-backup
-- This script is restore-ready: creates schema/table and replaces docs data
BEGIN;

CREATE SCHEMA IF NOT EXISTS w4h;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS w4h.docs (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  slug text COLLATE pg_catalog."default" NOT NULL,
  title text COLLATE pg_catalog."default",
  card_title text COLLATE pg_catalog."default",
  description text COLLATE pg_catalog."default",
  action_label text COLLATE pg_catalog."default",
  doc_type text COLLATE pg_catalog."default",
  sort_order integer,
  hidden boolean,
  updated_at timestamp without time zone,
  is_feature_card boolean,
  show_in_docs boolean,
  md text COLLATE pg_catalog."default",
  html text COLLATE pg_catalog."default",
  toc jsonb,
  card_order integer,
  CONSTRAINT docs_pkey PRIMARY KEY (id),
  CONSTRAINT docs_slug_key UNIQUE (slug)
);

CREATE INDEX IF NOT EXISTS idx_docs_slug ON w4h.docs(slug);

TRUNCATE TABLE w4h.docs;

-- Content rows intentionally omitted.
-- Docs are imported from the documentation repository and user edits persisted in w4h.docs.

COMMIT;
